/* @autogenerated */
package net.civeira.phylax.feature.observe.sourcemap;

import java.nio.file.Path;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class SourceMapsUnitTest {

  /** main.js line 1: column 0 → order.ts 10:4 "load"; column 20 → order.ts 12:2 (no name). */
  private static final String MAP =
      "{\"version\":3,\"file\":\"main.js\",\"sourceRoot\":\"webpack:///\","
          + "\"sources\":[\"src/app/order.ts\"],\"names\":[\"load\"],\"mappings\":\"AASIA,oBAEF\"}";

  @TempDir
  Path dir;

  @Test
  @DisplayName("Base64 VLQ values")
  void vlq() {
    Assertions.assertArrayEquals(new int[] {0, 0, 0, 0}, SourceMap.vlq("AAAA"));
    Assertions.assertArrayEquals(new int[] {1}, SourceMap.vlq("C"));
    Assertions.assertArrayEquals(new int[] {-1}, SourceMap.vlq("D"));
    Assertions.assertArrayEquals(new int[] {16}, SourceMap.vlq("gB"));
  }

  @Test
  @DisplayName("Generated positions are looked up to their original source, line, column and name")
  void lookup() throws Exception {
    SourceMap map = SourceMap.parse(MAP);
    SourceMap.Position first = map.lookup(1, 5).orElseThrow();
    Assertions.assertEquals("webpack:///src/app/order.ts", first.source());
    Assertions.assertEquals(10, first.line());
    Assertions.assertEquals("load", first.name());
    SourceMap.Position second = map.lookup(1, 30).orElseThrow();
    Assertions.assertEquals(12, second.line());
    Assertions.assertTrue(map.lookup(2, 1).isEmpty());
  }

  @Test
  @DisplayName("A frame of a release with its map is translated; without map it is not")
  void symbolicate() throws Exception {
    SourceMaps maps = new SourceMaps(dir.toString());
    maps.store("ui", "1.4.2", "main.4f2a9c.js.map", MAP);
    String frame = "    at Object.x (https://app.test/main.4f2a9c.js?v=1:1:5)";
    Assertions.assertEquals("    at load (webpack:///src/app/order.ts:10:5)",
        maps.symbolicate("ui", "1.4.2", frame).orElseThrow());
    Assertions.assertTrue(maps.symbolicate("ui", "1.4.1", frame).isEmpty());
    Assertions
        .assertTrue(maps.symbolicate("ui", "1.4.2", "\tat com.acme.Svc.run(Svc.java:3)").isEmpty());
  }

  @Test
  @DisplayName("Only the newest keep-releases releases of a source keep their maps")
  void keepReleases() throws Exception {
    SourceMaps maps = new SourceMaps(dir.toString());
    maps.keepReleases = 2;
    long now = System.currentTimeMillis();
    maps.store("ui", "1.0.0", "main.js.map", MAP);
    java.nio.file.Files.setLastModifiedTime(dir.resolve("sourcemaps/ui/1.0.0"),
        java.nio.file.attribute.FileTime.fromMillis(now - 20_000));
    maps.store("ui", "1.1.0", "main.js.map", MAP);
    java.nio.file.Files.setLastModifiedTime(dir.resolve("sourcemaps/ui/1.1.0"),
        java.nio.file.attribute.FileTime.fromMillis(now - 10_000));
    maps.store("other", "0.1.0", "main.js.map", MAP);
    maps.store("ui", "1.2.0", "main.js.map", MAP);
    Assertions.assertFalse(java.nio.file.Files.exists(dir.resolve("sourcemaps/ui/1.0.0")));
    Assertions.assertTrue(java.nio.file.Files.exists(dir.resolve("sourcemaps/ui/1.1.0")));
    Assertions
        .assertTrue(java.nio.file.Files.exists(dir.resolve("sourcemaps/ui/1.2.0/main.js.map")));
    Assertions.assertTrue(java.nio.file.Files.exists(dir.resolve("sourcemaps/other/0.1.0")));
  }

  @Test
  @DisplayName("The names of an upload cannot leave their folder")
  void safeNames() {
    Assertions.assertEquals("passwd", SourceMaps.safe("../../etc/passwd"));
    Assertions.assertEquals("1.4.2_beta", SourceMaps.safe("1.4.2 beta"));
    Assertions.assertThrows(IllegalArgumentException.class, () -> SourceMaps.safe(".."));
  }
}
